illinois_other_property_asset_exemptions.procedure:
def apply(inputs, premises):
    answer = {}
    count = min(len(inputs["asset_names"]), len(inputs["asset_values"]), len(inputs["other_property_applies"]))
    for i in range(count):
        name = inputs["asset_names"][i]
        answer[name] = []
        if inputs["other_property_applies"][i]:
            if inputs["include_claim_values"]:
                value = min(inputs["asset_values"][i], inputs["other_property_limit"])
                answer[name] = [{"citation": inputs["other_property_citation"], "claim_value": value}]
            else:
                answer[name] = [inputs["other_property_citation"]]
    return {"answer": answer}

section1_tax_amount_claim.procedure:
def apply(inputs, premises):
    count = min(len(inputs["bracket_subsections"]), len(inputs["bracket_upper_bounds"]), len(inputs["bracket_base_amounts"]), len(inputs["bracket_excess_floors"]), len(inputs["bracket_rates"]))
    applicable = -1
    for i in range(count):
        if inputs["bracket_upper_bounds"][i] < 0 or inputs["taxable_income"] <= inputs["bracket_upper_bounds"][i]:
            applicable = i
            break
    answer = "Contradiction"
    if applicable >= 0:
        expected_tax = inputs["bracket_base_amounts"][applicable] + inputs["bracket_rates"][applicable] * (inputs["taxable_income"] - inputs["bracket_excess_floors"][applicable])
        if inputs["claimed_subsection"] == inputs["bracket_subsections"][applicable] and abs(inputs["claimed_tax_amount"] - expected_tax) < 0.005:
            answer = "Entailment"
    return {"answer": answer}

